#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>
constexpr int TILE_A = 16;
constexpr int TILE_B = 8;
constexpr int TILE_L = 10;
constexpr int TILE_C = 3;
constexpr int TILE_CO = 16;
constexpr int CO_CHUNK = 8;
static_assert(TILE_CO % CO_CHUNK == 0, "TILE_CO must be divisible by CO_CHUNK");
constexpr int TILE_THREADS = 256;
constexpr int OUTPUTS_PER_THREAD =
    (TILE_A * TILE_B * TILE_L + TILE_THREADS - 1) / TILE_THREADS;
extern "C" __global__ void __launch_bounds__(TILE_THREADS, 2) conv3d_k331_s1_p0_d1_g1_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ y,
    const int N,
    const int Cin,
    const int A,
    const int B,
    const int L,
    const int Cout,
    const int Aout,
    const int Bout,
    const bool has_bias
) {
