    const long long tiles_b = (Bout + TILE_B - 1) / TILE_B;
    const long long tiles_l = (L + TILE_L - 1) / TILE_L;
    const long long tiles_co = (Cout + TILE_CO - 1) / TILE_CO;
    long long t = blockIdx.x;
    const int ta = (int)(t % tiles_a);
    t /= tiles_a;
    const int tb = (int)(t % tiles_b);
    t /= tiles_b;
    const int tl = (int)(t % tiles_l);
    const int n = (int)(t / tiles_l);
    const int a0 = ta * TILE_A;
    const int b0 = tb * TILE_B;
    const int l0 = tl * TILE_L;
    __shared__ float xs[TILE_C][TILE_A + 2][TILE_B + 2][TILE_L];
    __shared__ float ws[TILE_CO][TILE_C][9];
    int out_a[OUTPUTS_PER_THREAD];
    int out_b[OUTPUTS_PER_THREAD];
    int out_l[OUTPUTS_PER_THREAD];
    #pragma unroll
    for (int j = 0; j < OUTPUTS_PER_THREAD; ++j) {
        const int pos = threadIdx.x + j * TILE_THREADS;
        out_l[j] = pos % TILE_L;
        const int spatial = pos / TILE_L;
        out_b[j] = spatial % TILE_B;
        out_a[j] = spatial / TILE_B;
    }
    for (int c0 = 0; c0 < Cin; c0 += TILE_C) {
        const int x_tile_elements = TILE_C * (TILE_A + 2) * (TILE_B + 2) * TILE_L;
        for (int q = threadIdx.x; q < x_tile_elements; q += TILE_THREADS) {
            const int l = q % TILE_L;
            int r = q / TILE_L;
            const int ib = r % (TILE_B + 2);
            r /= (TILE_B + 2);
            const int ia = r % (TILE_A + 2);
            const int c = r / (TILE_A + 2);
            const int global_c = c0 + c;
            const int global_a = a0 + ia;
            const int global_b = b0 + ib;
            const int global_l = l0 + l;
            float value = 0.0f;
            if (global_c < Cin && global_a < A && global_b < B && global_l < L) {
                value = x[((((long long)n * Cin + global_c) * A + global_a) * B + global_b) * L + global_l];
            }
            xs[c][ia][ib][l] = value;
        }
        __syncthreads();
        for (long long tco = 0; tco < tiles_co; ++tco) {
            const int co0 = (int)(tco * TILE_CO);
            const int w_tile_elements = TILE_CO * TILE_C * 9;
            for (int q = threadIdx.x; q < w_tile_elements; q += TILE_THREADS) {
                const int k = q % 9;
                const int r = q / 9;
                const int c = r % TILE_C;
                const int co = r / TILE_C;
                const int global_co = co0 + co;
                const int global_c = c0 + c;
                float value = 0.0f;
