                #pragma unroll
                for (int j = 0; j < OUTPUTS_PER_THREAD; ++j) {
                    const int global_a = a0 + out_a[j];
                    const int global_b = b0 + out_b[j];
                    const int global_l = l0 + out_l[j];
                    const bool spatial_valid = (global_a < Aout && global_b < Bout && global_l < L);
