                        #pragma unroll
                        for (int kb = 0; kb < 3; ++kb) {
                            float xv[OUTPUTS_PER_THREAD];
                            #pragma unroll
                            for (int j = 0; j < OUTPUTS_PER_THREAD; ++j) {
                                xv[j] = xs[c][out_a[j] + ka][out_b[j] + kb][out_l[j]];
                            }
